    if(!p.earned[k]&&mimoRewardEligibleMX({...r,target},a)){const e={id:k,title:g?.title||r.title,item:r.item,real:r.real,category:r.category||'🎁',date:today(),claimed:false};p.earned[k]=e;newly.push(e);}
