/* Complete media backup v2; old v1 exports remain importable. */
function mxBackupMediaKey(key){return typeof key==='string'&&key.length<=180&&(/^(p90-(?:[1-9]|1[0-2])|mx-(?:audio|original|lesson)-[\w-]+|mx-focus-sound-(?:start|break|resume|complete|task|trophy)|mx-mimo-audio-[\w-]+|mx-mimo-character-pack-v2)$/.test(key));}
function mxValidPack(pack){return pack&&typeof pack==='object'&&pack.animations&&typeof pack.animations==='object'&&Object.keys(pack.animations).length<=11&&!!pack.animations.idle&&Object.entries(pack.animations).every(([k,v])=>['idle','happy','love','knead','walk','still','greet','sad','play','sleep','gift'].includes(k)&&v&&['image/gif','image/png','image/webp'].includes(v.mime)&&typeof v.base64==='string'&&v.base64.length<=2500000&&/^[A-Za-z0-9+/]+={0,2}$/.test(v.base64));}
function installBackupAuditMX(){
 if(window.mxBackupAuditReady)return;window.mxBackupAuditReady=true;
 const originalParse=parseBackup8,originalApply=applyBackup8;
 function mediaAll(){return new Promise((resolve,reject)=>{const entries=[],tx=db6.transaction('media'),req=tx.objectStore('media').openCursor();req.onsuccess=()=>{const cur=req.result;if(!cur)return;if(mxBackupMediaKey(cur.key)&&(cur.value instanceof Blob||cur.key==='mx-mimo-character-pack-v2'&&mxValidPack(cur.value)))entries.push([cur.key,cur.value]);cur.continue();};tx.oncomplete=()=>resolve(entries);tx.onabort=()=>reject(tx.error||Error('Medya okunamadı.'));tx.onerror=()=>reject(tx.error||Error('Medya okunamadı.'));});}
 backupWithMedia8=async function(){if(!db6)return toast('Yerel medya deposu açılamadı.');try{clockFlush9();const state=structuredClone(S),media=[];for(const [key,value] of await mediaAll()){if(key==='mx-mimo-character-pack-v2'&&!(value instanceof Blob)){media.push({key,kind:'pack',value});continue;}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(value);});media.push({key,kind:'blob',type:value.type,name:value.name||'',data});}downloadBackup8({format:backupFormat8,version:2,state,media},'muses-tam-yedek');toast('Kayıt ve medya yedeği hazır.');}catch(e){toast('Tam yedek oluşturulamadı: '+e.message);}};
 parseBackup8=function(value){if(value?.format!==backupFormat8||value.version!==2)return originalParse(value);if(!Array.isArray(value.media))throw Error('Medya listesi geçersiz.');const state=validate8(value.state),keys=new Set();const media=value.media.map(item=>{if(!item||!mxBackupMediaKey(item.key)||keys.has(item.key))throw Error('Medya anahtarı geçersiz veya tekrar ediyor.');keys.add(item.key);if(item.kind==='pack'){if(item.key!=='mx-mimo-character-pack-v2'||!mxValidPack(item.value))throw Error('Animasyon paketi geçersiz.');return [item.key,item.value];}if(item.kind!=='blob'||item.key==='mx-mimo-character-pack-v2'||typeof item.data!=='string'||typeof item.name!=='string'||typeof item.type!=='string')throw Error('Medya verisi geçersiz.');const raw=atob(item.data);if(btoa(raw)!==item.data)throw Error('Medya verisi bozuk.');return [item.key,new File([Uint8Array.from(raw,c=>c.charCodeAt(0))],item.name,{type:item.type})];});return {state,media};};
 applyBackup8=async function(data){const clean=Object.fromEntries(Object.entries(data.state.v6?.mediaNames||{}));const ok=await originalApply(data);if(ok){for(const [key] of data.media)if(!/^p90-/.test(key)){const generated=key.slice(4);if(Object.hasOwn(clean,generated))v6().mediaNames[generated]=clean[generated];else delete v6().mediaNames[generated];}save();if(data.media.length)toast('Medya geri yüklendi. Animasyon ve seslerin yenilenmesi için uygulamayı yeniden aç.');}return ok;};
 const oldSettings=settings;settings=function(){return '<section class="card"><h3>Tam cihaz yedeği</h3><p>Görevler, ilerleme, kitaplar, özgün belgeler, sesler, videolar ve kişisel kedi animasyonları. Bu yedek özeldir; GitHub’a yükleme.</p><button class="primary" onclick="backupWithMedia8()">Kayıt ve medyayı yedekle</button><button onclick="backup()">Yalnız kayıtları yedekle</button></section>'+oldSettings();};
}
