   const form=document.querySelector('#mx-source-task'),source=form.elements.source,pick=form.elements.leaf,query=form.elements.search;const unitRow=document.createElement('div');unitRow.className='mx-edit-grid';unitRow.innerHTML='<label>Her alt görev için miktar<input type="number" value="1" readonly></label><label>Birim<select name="mxUnit">'+opt5(['bölüm','adet','sayfa','part','ünite','ders','video','DVD','bulmaca'].map(x=>[x,x]),existing?.unit||'bölüm')+'</select></label>';pick.closest('label').after(unitRow);const srcSearch=document.createElement('input');srcSearch.type='search';srcSearch.placeholder='Kaynak ara';source.before(srcSearch);srcSearch.oninput=()=>{const q=srcSearch.value.toLocaleLowerCase('tr');for(const o of source.options)o.hidden=!o.textContent.toLocaleLowerCase('tr').includes(q);};
