 let page='dashboard',group='all',groups=new Set(),selection=new Set(),filter='all',kind='',query='',period=7,offset=0,lastView='',anchor=-1,drag=null,settings=false,legacy=false,lastSpeech='',detailRange=null,detailKind='all',detailQuery='';const expandedFolders=new Set(db().expandedFolders||['cefr','sources','english-file']);let fullStudy=false,chosenPractice=[],chooseFrom='list',listScroll=0,previousPage='',mapPage=0,mapQuery='',mapLevel='All',mapSelected='';
 const display=(w,f)=>{const v=val(w,f);if(!v)return '';if(f==='Image URL'){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?'<img class="mxv-image" alt="" loading="lazy" src="'+H(u.href)+'" onerror="this.hidden=true">':'';}catch{return '';}}return '<div class="mxv-field '+(f==='Word / Phrase'?'mxv-term':f==='POS'?'mxv-pos':'')+'">'+(!['Word / Phrase','POS'].includes(f)?'<small>'+H(names[fields.indexOf(f)]||f)+'</small>':'')+H(v).replace(/\n/g,'<br>')+'</div>';};
 const groupRows=(m)=>{const out=[{id:'all',name:'Tüm kelimeler',keys:[...m.keys()],folder:'system'}];for(const l of ['A1','A2','B1','B2','C1','C2'])out.push({id:'cefr:'+l,name:l,folder:'cefr',keys:[...m].filter(([k,w])=>level(w).includes(l)).map(([k])=>k)});const sources=new Map(),ef=new Set();for(const [k,w] of m){const original=String(w.Source||'').trim(),src=/fono/i.test(original)?'Fono':original;if(src){if(!sources.has(src))sources.set(src,[]);sources.get(src).push(k);if(/english[\s_-]*file/i.test(src))ef.add(k);}}if(ef.size)out.push({id:'src:English File',name:'English File · Tümü',folder:'english-file',keys:[...ef]});for(const [name,keys] of sources){const isEF=/english[\s_-]*file/i.test(name);if(isEF&&/^english[\s_-]*file$/i.test(name))continue;out.push({id:'src:'+name,name,folder:isEF?'english-file':'sources',keys});}return out.concat(db().lists.map(l=>({...l,keys:l.keys.filter(k=>m.has(k))}))).map(x=>({...x,folder:x.id==='all'?'system':(db().moves[x.id]??x.folder)}));};
