 function shuffledMXV(values){const a=[...values];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
 function quizOptions(s,k,w,m){if(s.quiz?.key===k)return s.quiz.options;const correct=val(w,s.cfg.answer),norm=x=>String(x).normalize('NFKC').trim().toLocaleLowerCase('tr'),seen=new Set([norm(correct)]),wrong=[];for(const key of shuffledMXV([...m.keys()])){if(key===k)continue;const v=val(m.get(key),s.cfg.answer),n=norm(v);if(!n||seen.has(n))continue;seen.add(n);wrong.push(v);if(wrong.length===3)break;}s.quiz={key:k,options:shuffledMXV([correct,...wrong])};save();return s.quiz.options;}
