 const oldTree=sourceTree;
 sourceTree=function(r){const base=oldTree(r),d=data();if(!isEF(r)||!d.imported||!Array.isArray(base))return base;const makePage=(p,u)=>({id:pageId(p),title:pageTitle(p),note:p===39?'Grammar, silent consonants, speaking':p===146?'Have to, must, should — Grammar Bank':'English File · '+u.id,amount:1,unit:'Sayfa'});return [...base.filter(n=>n.id!=='mx-ef-pages'),{id:'mx-ef-pages',title:'Sayfa bazında çalışma',children:d.units.map(u=>({id:'mx-ef-unit-'+u.id,title:u.id+' · '+u.title,children:[...Array.from({length:u.end-u.start+1},(_,i)=>makePage(u.start+i,u)),...(u.id==='4A'?[makePage(146,u)]:[])]}))}];};
