  S.words??=[];const current=new Map(),byTerm=new Map();for(const w of [...(Array.isArray(S.words)?S.words:[]),...(Array.isArray(all4)?all4:[])]){if(!w?.['Word / Phrase'])continue;const k=key4(w),name=canonical(w['Word / Phrase']);current.set(k,w);if(!byTerm.has(name))byTerm.set(name,[]);if(!byTerm.get(name).some(x=>key4(x)===k))byTerm.get(name).push(w);}
