/* Route transitions close the prior dialog; keep forms and same-screen edits intact. */
function installCleanNavigationMX(){
 if(window.mxCleanNavigationReady)return;window.mxCleanNavigationReady=true;
 const oldGo=go;go=function(next,...args){const changed=next!==view;if(changed){if(document.body.classList.contains('mx-modal-active')||document.querySelector('dialog[open]'))close5();document.body.classList.remove('mxv-focus-screen');}const result=oldGo(next,...args);if(changed){requestAnimationFrame(()=>{window.scrollTo(0,0);for(const node of document.querySelectorAll('#app,[role=main]'))if(node.scrollTop)node.scrollTop=0;});}return result;};
 const oldModal=modal5,oldClose=close5;modal5=function(...args){const result=oldModal(...args);const head=[...document.querySelectorAll('.modalhead5')].filter(x=>x.getClientRects().length).at(-1),dialog=document.querySelector('dialog[open]')||head?.parentElement;if(dialog){dialog.scrollTop=0;dialog.classList.add('mx-route-dialog');document.body.classList.add('mx-modal-active');}return result;};close5=function(...args){document.body.classList.remove('mx-modal-active');return oldClose(...args);};
}
