function installSearchAndMilestonesMX(){if(window.mxSearchMilestonesReady)return;window.mxSearchMilestonesReady=true;let qGoal='',qResource='';const prior=render;function filterGoals(){const q=qGoal.toLocaleLowerCase('tr').trim();for(const el of document.querySelectorAll('[data-mx-goal-title]')){const card=el.closest('article')||el.parentElement;if(card)card.hidden=!!q&&!el.dataset.mxGoalTitle.toLocaleLowerCase('tr').includes(q);}}render=function(){prior();const f=document.querySelector('#mx-goal-search');if(f){f.value=qGoal;filterGoals();f.oninput=()=>{qGoal=f.value;filterGoals();};}const host=document.querySelector('#app');if(host&&!host.querySelector('.mx-global-search')){const b=document.createElement('button');b.className='mx-global-search';b.textContent='⌕';b.title='Uygulamada ara';b.setAttribute('aria-label','Uygulamada ara');b.onclick=()=>openPaletteP1();host.prepend(b);}const medals=S.mxGoalMilestones??={};let changed=false;for(const g of v5().challenges){const p=challengeInfo5(g),ratio=p.target>0?p.count/p.target:0;const entry=medals[g.id]??={};for(const mark of [25,50,75,100])if(ratio*100>=mark&&!entry[mark]){entry[mark]={date:today(),points:25};changed=true;}}if(changed)save();};}
